/* NEXZO Dashboard Controller v2 — renders only canonical task/profile data. */
(function(){
  'use strict';
  if(document.body?.dataset.page!=='dashboard'||window.__NEXZO_DASHBOARD_V2__)return;
  window.__NEXZO_DASHBOARD_V2__=true;
  const $=id=>document.getElementById(id);const esc=window.NEXZOShell?.esc||((v)=>String(v??''));const num=v=>Number.isFinite(Number(v))?Number(v):0;
  let range=7,focusSeconds=1500,focusTimer=null;
  const tasks=()=>window.NEXZOTaskStore?.getAll?.()||[];const allTasks=()=>window.NEXZOTaskStore?.getAll?.({includeSystem:true})||tasks();
  const profile=()=>window.NEXZOStateAuthority?.profile?.()||window.NEXZODataService?.getProfile?.()||{};
  const stats=()=>window.NEXZOStateAuthority?.stats?.()||{total:0,completed:0,pending:0,overdue:0,weekMinutes:0,totalMinutes:0,streak:0,accuracy:0,progress:0,byDay:{}};
  function set(id,value){const el=$(id);if(el)el.textContent=String(value)}
  function fmtMin(m){m=Math.max(0,Math.round(num(m)));const h=Math.floor(m/60),min=m%60;return min?`${h}h ${min}m`:`${h}h`}
  function dateKey(ms){const d=new Date(ms);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function taskTime(t){const minutes=window.NEXZOTaskStore?.recordedMinutes?.(t);return Number.isFinite(Number(minutes))?Number(minutes)*60000:(window.NEXZOTaskStore?.elapsedMs?.(t)||num(t.elapsed))}
  function greeting(){const h=new Date().getHours();return h<12?'Good Morning':h<17?'Good Afternoon':'Good Evening'}
  function dailyMinutes(days){
    const byDay=stats().byDay||{};
    const out=[];
    for(let i=days-1;i>=0;i--){
      const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i);
      const key=dateKey(d);
      out.push({date:d,key,minutes:Math.round(num(byDay[key])/60000)});
    }
    return out;
  }
  function chart(data){const svg=$('dashDynamicChart');if(!svg)return;const W=460,H=220,p=28,max=Math.max(60,...data.map(x=>x.minutes));const points=data.map((x,i)=>{const px=p+i*((W-p*2)/Math.max(1,data.length-1));const py=H-p-(x.minutes/max)*(H-p*2);return [px,py,x]});const line=points.map(x=>`${x[0]},${x[1]}`).join(' ');svg.innerHTML=`<defs><linearGradient id="nxDashArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--nx-user-accent,#8b5cf6)" stop-opacity=".42"/><stop offset="1" stop-color="var(--nx-user-accent,#8b5cf6)" stop-opacity="0"/></linearGradient></defs><line x1="${p}" y1="${H-p}" x2="${W-p}" y2="${H-p}" stroke="rgba(255,255,255,.18)"/><polygon points="${p},${H-p} ${line} ${W-p},${H-p}" fill="url(#nxDashArea)"/><polyline points="${line}" fill="none" stroke="var(--nx-user-accent,#8b5cf6)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>${points.map(([x,y,row])=>`<circle cx="${x}" cy="${y}" r="5" fill="#fff"><title>${row.date.toLocaleDateString()}: ${fmtMin(row.minutes)}</title></circle>`).join('')}${points.map(([x,,row],i)=>`<text x="${x}" y="${H-5}" text-anchor="middle" fill="currentColor" opacity=".65" font-size="11">${range===7?row.date.toLocaleDateString('en',{weekday:'short'}):(i%5===0?row.date.getDate():'')}</text>`).join('')}`;}
  function heatmap(){const box=$('dashHeatmapExact');if(!box)return;const values=dailyMinutes(84);const max=Math.max(1,...values.map(x=>x.minutes));box.innerHTML=values.map(x=>{const level=x.minutes===0?0:Math.max(1,Math.ceil(x.minutes/max*4));return `<i data-level="${level}" title="${x.date.toLocaleDateString()}: ${fmtMin(x.minutes)}"></i>`}).join('');}
  function upcoming(){const box=$('dashUpcomingTasksExact');if(!box)return;const list=tasks().filter(t=>!t.completed).sort((a,b)=>(num(a.deadlineMs)||Infinity)-(num(b.deadlineMs)||Infinity)).slice(0,6);box.innerHTML=list.length?list.map(t=>`<article><span class="dash-task-dot" style="--x:${t.priority==='Urgent'||t.priority==='High'?'#ef4444':t.priority==='Medium'?'#f59e0b':'#22c55e'}"></span><div><b>${esc(t.title)}</b><small>${esc(t.subject)} • ${esc(t.taskType||t.type)}${t.deadline?` • ${esc(t.deadline)}`:''}</small></div><em>${t.running?'Running':t.status==='paused'?'Paused':'Pending'}</em></article>`).join(''):'<div class="nx-runtime-empty">No upcoming tasks. Create one in Planner.</div>';}
  function subjectProgress(){const box=$('dashSubjectProgressExact');if(!box)return;const map={};tasks().forEach(t=>{const k=t.subject||'General';map[k]??={total:0,done:0,minutes:0};map[k].total++;if(t.completed)map[k].done++;map[k].minutes+=Math.round(taskTime(t)/60000);});const rows=Object.entries(map).sort((a,b)=>b[1].minutes-a[1].minutes).slice(0,6);box.innerHTML=rows.length?rows.map(([name,x])=>{const p=x.total?Math.round(x.done/x.total*100):0;return `<div class="dash-subject-row"><div><b>${esc(name)}</b><small>${x.done}/${x.total} tasks • ${fmtMin(x.minutes)}</small></div><span>${p}%</span><div class="dash-subject-bar"><i style="width:${p}%"></i></div></div>`}).join(''):'<div class="nx-runtime-empty">Your subject progress will appear after creating tasks.</div>';}
  function activity(){const box=$('dashRecentActivityExact');if(!box)return;const rows=tasks().map(t=>({ms:num(t.completedAtMs)||num(t.updatedAtMs)||num(t.createdAtMs),icon:t.completed?'✅':t.running?'▶':'📌',title:t.completed?`Completed ${t.title}`:t.running?`Started ${t.title}`:`Created ${t.title}`,sub:`${t.subject||'General'}${t.score?` • ${num(t.score).toFixed(1)}/10`:''}`})).sort((a,b)=>b.ms-a.ms).slice(0,6);box.innerHTML=rows.length?rows.map(x=>`<div class="dash-activity-row"><i>${x.icon}</i><div><b>${esc(x.title)}</b><small>${esc(x.sub)} • ${new Date(x.ms).toLocaleString()}</small></div></div>`).join(''):'<div class="nx-runtime-empty">No activity yet.</div>';}
  function suggestions(s){const box=$('dashAiSuggestionsExact');if(!box)return;const list=[];if(!s.total)list.push(['Create your first plan','Use Planner to create a focused study task.','planner.html']);else{if(s.overdue)list.push(['Handle overdue tasks',`${s.overdue} task${s.overdue>1?'s':''} need attention.`,'planner.html']);if(s.weekMinutes<120)list.push(['Build consistency','Try a 25-minute focus session today.','planner.html']);if(s.accuracy&&s.accuracy<70)list.push(['Improve weak answers','Review AI feedback and resubmit incomplete work.','planner.html']);if(s.completed===s.total)list.push(['Plan your next goal','All current tasks are completed. Add the next milestone.','planner.html']);}if(!list.length)list.push(['You are on track','Continue the next pending task and protect your streak.','planner.html']);box.innerHTML=list.slice(0,4).map(([a,b,c])=>`<a class="dash-suggestion-row" href="${c}"><i>✦</i><div><b>${esc(a)}</b><small>${esc(b)}</small></div><span>→</span></a>`).join('');}
  function achievements(s){const box=$('dashAchievements');if(!box)return;const rows=[['🔥','First Streak',s.streak>=1],['✅','Task Starter',s.completed>=1],['🏆','Task Master',s.completed>=10],['⏱','Time Scholar',s.totalMinutes>=600],['🤖','AI Learner',s.accuracy>=70],['💯','Perfect Score',tasks().some(t=>num(t.score)>=10)]];box.innerHTML=rows.map(([i,n,u])=>`<div class="dash-achievement ${u?'unlocked':'locked'}"><i>${i}</i><b>${n}</b><small>${u?'Unlocked':'Locked'}</small></div>`).join('');}
  function productivity(s){const score=Math.round(Math.min(100,(s.progress*.4)+(Math.min(100,s.weekMinutes/5)*.3)+(s.accuracy*.2)+(Math.min(100,s.streak*12)*.1)));set('dashProductivityScore',`${score}%`);$('dashProductivityRing')?.style.setProperty('--score',`${score}%`);const box=$('dashInsightList');if(box)box.innerHTML=[s.weekMinutes?`You studied ${fmtMin(s.weekMinutes)} this week.`:'Start a focus timer to record real study time.',s.completed?`${s.completed} task${s.completed>1?'s':''} verified.`:'Complete a task to build your progress.',s.streak?`${s.streak}-day completion streak.`:'Complete one task today to start a streak.'].map(x=>`<p>✓ ${esc(x)}</p>`).join('');}
  function render(){const s=stats(),p=profile(),info=window.NEXZOShell?.identity?.()||{name:'Student'};set('dashGreeting',`${greeting()}, ${info.name.split(' ')[0]}! 👋`);set('dashWelcomeLine',s.total?'Your real Planner activity is synced here.':'Create your first Planner task to start the dashboard.');const now=new Date();set('dashDate',now.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}));set('dashDay',now.toLocaleDateString('en',{weekday:'long'}));set('dashStreak',s.streak);set('dashBestStreak',s.streak?`${s.streak} day active streak`:'Complete a task today');set('dashTasksDone',s.completed);set('dashTaskRatio',`of ${s.total} tasks`);set('dashHours',fmtMin(s.totalMinutes));set('dashWeeklyHours',fmtMin(s.weekMinutes));set('dashAiScore',s.accuracy);set('dashProgress',`${s.progress}%`);set('dashMissionText',s.total?`${s.pending} remaining`:'Start your journey');{const lv=window.NEXZOStateAuthority?.level?.()?.level||window.NEXZOLevelSystem?.resolve?.(Math.max(0,num(p.xp)))?.level||1;set('dashLevelText',`Level ${lv}`);}const data=dailyMinutes(range);const combined=dailyMinutes(range*2),previous=combined.slice(0,range);const currentMinutes=data.reduce((a,x)=>a+x.minutes,0),previousMinutes=previous.reduce((a,x)=>a+x.minutes,0);const trend=previousMinutes?Math.round((currentMinutes-previousMinutes)/previousMinutes*100):(currentMinutes?100:0);set('dashTrend',`${trend>=0?'▲':'▼'} ${Math.abs(trend)}%`);set('dashHoursDelta',s.weekMinutes?`${fmtMin(s.weekMinutes)} this week`:(s.totalMinutes?'No study logged this week':'No recorded study sessions'));set('dashNotifCount',(window.NEXZOShell?.notifications?.()||[]).filter(x=>!x.read).length);chart(data);heatmap();upcoming();subjectProgress();activity();suggestions(s);achievements(s);productivity(s);const goal=Math.min(5,s.completed);set('dashGoalText',goal>=5?'Weekly goal completed!':`${5-goal} more completion${5-goal===1?'':'s'} to reach the goal.`);set('dashGoalCount',`${goal} / 5`);$('dashGoalBar')?.style.setProperty('width',`${goal/5*100}%`);}
  function focusText(){const m=Math.floor(focusSeconds/60),s=focusSeconds%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
  function updateFocus(){set('dashFocusTime',focusText());set('dashTopTimer',focusText());set('dashFocusStatus',focusTimer?'Focus session running':'Ready to focus?');set('dashFocusStart',focusTimer?'⏸ Pause Session':'▶ Start Session')}
  function toggleFocus(){if(focusTimer){clearInterval(focusTimer);focusTimer=null;updateFocus();return}focusTimer=setInterval(()=>{focusSeconds=Math.max(0,focusSeconds-1);if(!focusSeconds){clearInterval(focusTimer);focusTimer=null;window.NEXZOTaskStore?.recordFocusSession?.(25,Date.now());focusSeconds=1500;window.dispatchEvent(new CustomEvent('nexzo:focus-complete'));window.NEXZOShell?.addNotification?.('Focus session complete','Great work! Your 25-minute session was added to study time.','planner.html');window.NEXZOShell?.toast?.('Focus session complete and study time saved!','success');}localStorage.setItem('nexzo_dashboard_focus',String(focusSeconds));updateFocus();},1000);updateFocus();}
  function resetFocus(){clearInterval(focusTimer);focusTimer=null;focusSeconds=1500;localStorage.setItem('nexzo_dashboard_focus','1500');updateFocus()}
  function search(){const panel=$('dashSearchPanel');if(!panel)return;panel.hidden=false;panel.innerHTML=`<div class="nx-dash-search-card"><button data-close>×</button><input id="nxDashSearchInput" placeholder="Search your tasks..."><div id="nxDashSearchResults"></div></div>`;const input=$('nxDashSearchInput'),results=$('nxDashSearchResults');const draw=()=>{const q=(input.value||'').toLowerCase();const list=tasks().filter(t=>`${t.title} ${t.subject} ${t.type}`.toLowerCase().includes(q)).slice(0,10);results.innerHTML=list.length?list.map(t=>`<a href="planner.html"><b>${esc(t.title)}</b><small>${esc(t.subject)} • ${esc(t.status)}</small></a>`).join(''):'<p>No matching task.</p>'};input.addEventListener('input',draw);draw();input.focus();panel.onclick=e=>{if(e.target===panel||e.target.closest('[data-close]'))panel.hidden=true};}
  function showNotifications(){const list=window.NEXZOShell?.notifications?.()||[];window.NEXZOShell?.modal?.('Notifications',list.length?list.slice(0,15).map(x=>`<article class="nx-notification-row"><b>${esc(x.title)}</b><small>${esc(x.body||'')}</small></article>`).join(''):'<p>No notifications yet.</p>');}
  function bind(){$('dashRange')?.addEventListener('change',e=>{range=Number(e.target.value)||7;render()});$('dashFocusStart')?.addEventListener('click',toggleFocus);$('dashFocusReset')?.addEventListener('click',resetFocus);$('dashTimerTopBtn')?.addEventListener('click',toggleFocus);$('dashSearchBtn')?.addEventListener('click',search);$('dashNotifBtn')?.addEventListener('click',showNotifications);focusSeconds=Math.max(0,num(localStorage.getItem('nexzo_dashboard_focus'))||1500);updateFocus();}
  function init(){window.NEXZOShell?.layout?.('Dashboard');bind();window.NEXZOTaskStore?.subscribe?.(()=>render());['nexzo:profile-updated','nexzo:stats-updated'].forEach(n=>window.addEventListener(n,render));render();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
